"""Tensor-parallel linear layers (Megatron-LM style) built on PyTorch.

ColumnParallelLinear:  Y = X @ A + b, with A split column-wise (output dim)
                       across ranks; each rank computes its shard and the
                       result is all-gathered along the last dimension.

RowParallelLinear:     Y = X @ A + b, with A split row-wise (input dim)
                       across ranks; forward() receives the already-scattered
                       input shard and the partial outputs are all-reduced.
"""

import torch
import torch.distributed as dist

__all__ = ["ColumnParallelLinear", "RowParallelLinear"]


def _world_info():
    """(world_size, rank) working with or without an initialized process group."""
    try:
        if dist.is_available() and dist.is_initialized():
            return dist.get_world_size(), dist.get_rank()
    except Exception:
        pass
    return 1, 0


def _split_tensor(tensor, world_size, rank, dim):
    """Contiguous, equally sized shard of ``tensor`` along ``dim``."""
    if world_size == 1:
        return tensor.contiguous()
    size = tensor.size(dim)
    assert size % world_size == 0, (
        "dimension %d of size %d is not divisible by world size %d"
        % (dim, size, world_size)
    )
    chunk = size // world_size
    return tensor.narrow(dim, rank * chunk, chunk).contiguous()


class _AllGatherLastDim(torch.autograd.Function):
    """all_gather along the last dimension; backward keeps this rank's slice."""

    @staticmethod
    def forward(ctx, input_):
        world_size, rank = _world_info()
        ctx.world_size = world_size
        ctx.rank = rank
        if world_size == 1:
            return input_
        input_ = input_.contiguous()
        gathered = [torch.empty_like(input_) for _ in range(world_size)]
        dist.all_gather(gathered, input_)
        gathered[rank] = input_  # keep autograd-friendly identity for own shard
        return torch.cat(gathered, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        world_size, rank = ctx.world_size, ctx.rank
        if world_size == 1:
            return grad_output
        chunk = grad_output.size(-1) // world_size
        return grad_output.narrow(-1, rank * chunk, chunk).contiguous()


class _AllReduceSum(torch.autograd.Function):
    """all_reduce(SUM); backward is the identity."""

    @staticmethod
    def forward(ctx, input_):
        world_size, _ = _world_info()
        if world_size == 1:
            return input_
        output = input_.clone().contiguous()
        dist.all_reduce(output, op=dist.ReduceOp.SUM)
        return output

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


def _as_weight(master_weight):
    w = master_weight
    if not torch.is_tensor(w):
        w = torch.as_tensor(w)
    return w.detach()


class ColumnParallelLinear(torch.nn.Module):
    """Linear layer with the weight partitioned along its output dimension."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size, rank = _world_info()
        self.world_size = world_size
        self.rank = rank
        assert out_features % world_size == 0, (
            "out_features (%d) must be divisible by world size (%d)"
            % (out_features, world_size)
        )
        self.output_size_per_partition = out_features // world_size

        master = _as_weight(master_weight)
        # torch.nn.Linear layout: (out_features, in_features).  Splitting the
        # weight matrix by columns == splitting the output dimension.
        if master.shape == (in_features, out_features) and \
                master.shape != (out_features, in_features):
            master = master.t()
        weight_shard = _split_tensor(master, world_size, rank, dim=0)
        self.weight = torch.nn.Parameter(
            weight_shard.clone().to(dtype=master.dtype)
        )

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
            with torch.no_grad():
                self.bias.zero_()
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        output_parallel = torch.nn.functional.linear(input_, self.weight, self.bias)
        return _AllGatherLastDim.apply(output_parallel)

    def extra_repr(self):
        return "in_features={}, out_features={}, bias={}".format(
            self.in_features, self.out_features, self.bias is not None
        )


class RowParallelLinear(torch.nn.Module):
    """Linear layer with the weight partitioned along its input dimension."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size, rank = _world_info()
        self.world_size = world_size
        self.rank = rank
        assert in_features % world_size == 0, (
            "in_features (%d) must be divisible by world size (%d)"
            % (in_features, world_size)
        )
        self.input_size_per_partition = in_features // world_size

        master = _as_weight(master_weight)
        if master.shape == (in_features, out_features) and \
                master.shape != (out_features, in_features):
            master = master.t()
        # Splitting the weight matrix by rows == splitting the input dimension,
        # which is dim 1 of the (out_features, in_features) layout.
        weight_shard = _split_tensor(master, world_size, rank, dim=1)
        self.weight = torch.nn.Parameter(
            weight_shard.clone().to(dtype=master.dtype)
        )

        if bias:
            self.bias = torch.nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
            with torch.no_grad():
                self.bias.zero_()
        else:
            self.register_parameter("bias", None)

    def forward(self, input_):
        # ``input_`` is already the local shard along the last dimension.
        output_parallel = torch.nn.functional.linear(input_, self.weight)
        output = _AllReduceSum.apply(output_parallel)
        if self.bias is not None:
            output = output + self.bias
        return output

    def extra_repr(self):
        return "in_features={}, out_features={}, bias={}".format(
            self.in_features, self.out_features, self.bias is not None
        )
